#!/bin/bash

# Linux K8s 快速部署脚本
# 支持 Ubuntu、Debian、CentOS、RHEL 等 Linux 发行版

set -e

# 颜色定义
RED='\033[0;31m'\nGREEN='\033[0;32m'\nYELLOW='\033[1;33m'\nBLUE='\033[0;34m'\nNC='\033[0m'\n\n# 打印函数\nprint_info() {\n    echo -e \"${GREEN}[INFO]${NC} $1\"\n}\n\nprint_warn() {\n    echo -e \"${YELLOW}[WARN]${NC} $1\"\n}\n\nprint_error() {\n    echo -e \"${RED}[ERROR]${NC} $1\"\n}\n\nprint_step() {\n    echo -e \"${BLUE}[STEP]${NC} $1\"\n}\n\n# 检查命令是否存在\ncommand_exists() {\n    command -v \"$1\" >/dev/null 2>&1\n}\n\n# 检测 Linux 发行版\ndetect_distro() {\n    if [ -f /etc/os-release ]; then\n        . /etc/os-release\n        DISTRO=$ID\n        VERSION=$VERSION_ID\n    else\n        print_error \"无法检测 Linux 发行版\"\n        exit 1\n    fi\n    \n    print_info \"检测到发行版: $DISTRO $VERSION\"\n}\n\n# 安装 Docker\ninstall_docker() {\n    print_step \"安装 Docker...\"\n    \n    if command_exists docker; then\n        print_info \"Docker 已安装: $(docker --version)\"\n        return\n    fi\n    \n    case $DISTRO in\n        ubuntu|debian)\n            print_info \"为 Ubuntu/Debian 安装 Docker...\"\n            sudo apt-get update\n            sudo apt-get install -y \\\n                apt-transport-https \\\n                ca-certificates \\\n                curl \\\n                gnupg \\\n                lsb-release\n            \n            curl -fsSL https://download.docker.com/linux/ubuntu/gpg | sudo gpg --dearmor -o /usr/share/keyrings/docker-archive-keyring.gpg\n            \n            echo \\\n              \"deb [arch=amd64 signed-by=/usr/share/keyrings/docker-archive-keyring.gpg] https://download.docker.com/linux/ubuntu \\\n              $(lsb_release -cs) stable\" | sudo tee /etc/apt/sources.list.d/docker.list > /dev/null\n            \n            sudo apt-get update\n            sudo apt-get install -y docker-ce docker-ce-cli containerd.io docker-compose-plugin\n            ;;\n        centos|rhel|fedora)\n            print_info \"为 CentOS/RHEL/Fedora 安装 Docker...\"\n            sudo yum install -y yum-utils\n            sudo yum-config-manager --add-repo https://download.docker.com/linux/centos/docker-ce.repo\n            sudo yum install -y docker-ce docker-ce-cli containerd.io docker-compose-plugin\n            ;;\n        *)\n            print_error \"不支持的发行版: $DISTRO\"\n            exit 1\n            ;;\n    esac\n    \n    # 启动 Docker\n    sudo systemctl start docker\n    sudo systemctl enable docker\n    \n    # 添加当前用户到 docker 组\n    sudo usermod -aG docker $USER\n    \n    print_info \"Docker 安装完成\"\n}\n\n# 安装 kubectl\ninstall_kubectl() {\n    print_step \"安装 kubectl...\"\n    \n    if command_exists kubectl; then\n        print_info \"kubectl 已安装: $(kubectl version --client --short)\"\n        return\n    fi\n    \n    print_info \"下载 kubectl...\"\n    curl -LO \"https://dl.k8s.io/release/$(curl -L -s https://dl.k8s.io/release/stable.txt)/bin/linux/amd64/kubectl\"\n    \n    sudo install -o root -g root -m 0755 kubectl /usr/local/bin/kubectl\n    rm kubectl\n    \n    print_info \"kubectl 安装完成\"\n}\n\n# 安装 Minikube\ninstall_minikube() {\n    print_step \"安装 Minikube...\"\n    \n    if command_exists minikube; then\n        print_info \"Minikube 已安装: $(minikube version)\"\n        return\n    fi\n    \n    print_info \"下载 Minikube...\"\n    curl -LO https://github.com/kubernetes/minikube/releases/latest/download/minikube-linux-amd64\n    \n    sudo install minikube-linux-amd64 /usr/local/bin/minikube\n    rm minikube-linux-amd64\n    \n    print_info \"Minikube 安装完成\"\n}\n\n# 启动 Minikube\nstart_minikube() {\n    print_step \"启动 Minikube...\"\n    \n    if minikube status | grep -q \"Running\"; then\n        print_info \"Minikube 已在运行\"\n    else\n        print_warn \"启动 Minikube（这可能需要几分钟）...\"\n        minikube start \\\n            --cpus=4 \\\n            --memory=8192 \\\n            --disk-size=50g \\\n            --driver=docker\n    fi\n    \n    # 验证集群\n    print_info \"验证集群...\"\n    kubectl cluster-info\n    kubectl get nodes\n}\n\n# 构建镜像\nbuild_image() {\n    print_step \"构建 Docker 镜像...\"\n    \n    # 切换到 Minikube 的 Docker 环境\n    eval $(minikube docker-env)\n    \n    # 构建镜像\n    cd ..\n    print_info \"构建镜像（这可能需要几分钟）...\"\n    docker build -f docker/Dockerfile -t demo-cluster:latest .\n    cd docker\n    \n    # 加载镜像到 Minikube\n    print_info \"加载镜像到 Minikube...\"\n    minikube image load demo-cluster:latest\n    \n    print_info \"镜像构建完成\"\n}\n\n# 部署\ndeploy() {\n    print_step \"部署到 Kubernetes...\"\n    \n    # 创建命名空间\n    print_info \"创建命名空间...\"\n    kubectl apply -f k8s-namespace.yaml\n    \n    # 部署基础服务\n    print_info \"部署 PostgreSQL...\"\n    kubectl apply -f k8s-postgres.yaml\n    \n    print_info \"部署 ETCD...\"\n    kubectl apply -f k8s-etcd.yaml\n    \n    print_info \"部署 NATS...\"\n    kubectl apply -f k8s-nats.yaml\n    \n    # 等待基础服务就绪\n    print_info \"等待基础服务就绪...\"\n    print_warn \"这可能需要 1-2 分钟...\"\n    \n    kubectl wait --for=condition=ready pod -l app=postgres -n demo-cluster --timeout=300s || true\n    kubectl wait --for=condition=ready pod -l app=etcd -n demo-cluster --timeout=300s || true\n    kubectl wait --for=condition=ready pod -l app=nats -n demo-cluster --timeout=300s || true\n    \n    sleep 5\n    \n    # 部署游戏节点\n    print_info \"部署游戏节点...\"\n    kubectl apply -f k8s-game-nodes.yaml\n    \n    # 等待游戏节点就绪\n    print_info \"等待游戏节点就绪...\"\n    kubectl wait --for=condition=ready pod -l app=center -n demo-cluster --timeout=300s || true\n    kubectl wait --for=condition=ready pod -l app=gate -n demo-cluster --timeout=300s || true\n    kubectl wait --for=condition=ready pod -l app=game -n demo-cluster --timeout=300s || true\n    kubectl wait --for=condition=ready pod -l app=web -n demo-cluster --timeout=300s || true\n    \n    print_info \"部署完成！\"\n}\n\n# 显示状态\nshow_status() {\n    print_step \"显示部署状态...\"\n    \n    echo \"\"\n    print_info \"Pod 状态：\"\n    kubectl get pods -n demo-cluster\n    \n    echo \"\"\n    print_info \"服务状态：\"\n    kubectl get svc -n demo-cluster\n    \n    echo \"\"\n    print_info \"PVC 状态：\"\n    kubectl get pvc -n demo-cluster\n}\n\n# 显示访问信息\nshow_access_info() {\n    print_step \"访问信息...\"\n    \n    echo \"\"\n    echo \"=== 端口转发命令 ===\"\n    echo \"# Web 服务\"\n    echo \"kubectl port-forward svc/web 3013:3013 -n demo-cluster\"\n    echo \"\"\n    echo \"# Gate 服务\"\n    echo \"kubectl port-forward svc/gate 3011:3011 -n demo-cluster\"\n    echo \"\"\n    echo \"# PostgreSQL\"\n    echo \"kubectl port-forward svc/postgres 5432:5432 -n demo-cluster\"\n    echo \"\"\n    echo \"# ETCD\"\n    echo \"kubectl port-forward svc/etcd 2379:2379 -n demo-cluster\"\n    echo \"\"\n    echo \"# NATS\"\n    echo \"kubectl port-forward svc/nats 4222:4222 -n demo-cluster\"\n    echo \"\"\n    echo \"=== 查看日志 ===\"\n    echo \"# 查看所有日志\"\n    echo \"kubectl logs -f <pod-name> -n demo-cluster\"\n    echo \"\"\n    echo \"# 查看特定服务日志\"\n    echo \"kubectl logs -f -l app=web -n demo-cluster\"\n    echo \"\"\n    echo \"=== 常用命令 ===\"\n    echo \"# 查看 Pod 详情\"\n    echo \"kubectl describe pod <pod-name> -n demo-cluster\"\n    echo \"\"\n    echo \"# 进入 Pod\"\n    echo \"kubectl exec -it <pod-name> -n demo-cluster -- bash\"\n    echo \"\"\n    echo \"# 查看资源使用\"\n    echo \"kubectl top pods -n demo-cluster\"\n    echo \"\"\n    echo \"# 查看事件\"\n    echo \"kubectl get events -n demo-cluster\"\n    echo \"\"\n}\n\n# 清理部署\ncleanup() {\n    print_warn \"清理 Kubernetes 部署...\"\n    kubectl delete namespace demo-cluster --ignore-not-found=true\n    print_info \"清理完成\"\n}\n\n# 显示帮助\nshow_help() {\n    cat << EOF\n用法: $0 [命令]\n\n命令:\n  install     安装必要工具（Docker、kubectl、Minikube）\n  start       启动 Minikube 集群\n  build       构建 Docker 镜像\n  deploy      完整部署（包括安装、启动、构建、部署）\n  status      显示部署状态\n  access      显示访问信息\n  clean       清理部署\n  help        显示此帮助信息\n\n示例:\n  $0 install      # 安装工具\n  $0 start        # 启动集群\n  $0 build        # 构建镜像\n  $0 deploy       # 完整部署\n  $0 status       # 查看状态\n  $0 access       # 显示访问信息\n  $0 clean        # 清理部署\n\n快速开始:\n  $0 deploy       # 一键部署\n  kubectl port-forward svc/web 3013:3013 -n demo-cluster  # 访问 Web\nEOF\n}\n\n# 主程序\nmain() {\n    print_info \"Linux K8s 快速部署脚本\"\n    echo \"\"\n    \n    # 检测发行版\n    detect_distro\n    echo \"\"\n    \n    case \"${1:-deploy}\" in\n        install)\n            install_docker\n            echo \"\"\n            install_kubectl\n            echo \"\"\n            install_minikube\n            ;;\n        start)\n            start_minikube\n            ;;\n        build)\n            build_image\n            ;;\n        deploy)\n            install_docker\n            echo \"\"\n            install_kubectl\n            echo \"\"\n            install_minikube\n            echo \"\"\n            start_minikube\n            echo \"\"\n            build_image\n            echo \"\"\n            deploy\n            echo \"\"\n            show_status\n            echo \"\"\n            show_access_info\n            ;;\n        status)\n            show_status\n            ;;\n        access)\n            show_access_info\n            ;;\n        clean)\n            cleanup\n            ;;\n        help)\n            show_help\n            ;;\n        *)\n            print_error \"未知命令: $1\"\n            show_help\n            exit 1\n            ;;\n    esac\n}\n\n# 执行主程序\nmain \"$@\"\n